CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,phone VARCHAR(30),role ENUM('USER','NGO_OFFICER','GOV_OFFICER','DISTRICT_ADMIN','SUPER_ADMIN') DEFAULT 'USER',status ENUM('active','suspended','banned') DEFAULT 'active',trust_score DECIMAL(5,2) DEFAULT 50,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ngo_applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,organization_name VARCHAR(190) NOT NULL,registration_number VARCHAR(100),description TEXT,status ENUM('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',reviewed_by BIGINT UNSIGNED,review_note TEXT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,reviewed_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(reviewed_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS ngo_profiles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE NOT NULL,organization_name VARCHAR(190) NOT NULL,registration_number VARCHAR(100),description TEXT,phone VARCHAR(30),city VARCHAR(100),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS incidents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,reporter_id BIGINT UNSIGNED NOT NULL,description TEXT NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,address VARCHAR(255),category ENUM('stalking','harassment','assault','theft','accident','poor_lighting','unsafe_area','suspicious_activity','safe_zone','other') DEFAULT 'other',severity ENUM('low','medium','high','critical') DEFAULT 'low',ai_category VARCHAR(50),ai_severity VARCHAR(20),ai_confidence DECIMAL(5,4),classification_source ENUM('AI','RULE','ADMIN_CORRECTION') DEFAULT 'RULE',status ENUM('PENDING','ASSIGNED','UNDER_REVIEW','CONFIRMED','REJECTED','RESOLVED','ARCHIVED') DEFAULT 'PENDING',reviewer_id BIGINT UNSIGNED,review_note TEXT,reviewed_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(reporter_id) REFERENCES users(id),FOREIGN KEY(reviewer_id) REFERENCES users(id),INDEX(status),INDEX(severity),INDEX(category),INDEX(created_at));
CREATE TABLE IF NOT EXISTS incident_assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,incident_id BIGINT UNSIGNED NOT NULL,assignee_id BIGINT UNSIGNED NOT NULL,assigned_by BIGINT UNSIGNED NOT NULL,assigned_at DATETIME DEFAULT CURRENT_TIMESTAMP,status ENUM('ACTIVE','COMPLETED','CANCELLED') DEFAULT 'ACTIVE',FOREIGN KEY(incident_id) REFERENCES incidents(id),FOREIGN KEY(assignee_id) REFERENCES users(id),FOREIGN KEY(assigned_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS sos_alerts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,latitude DECIMAL(10,7) NOT NULL,longitude DECIMAL(10,7) NOT NULL,address VARCHAR(255),message TEXT,status ENUM('ACTIVE','ACKNOWLEDGED','RESOLVED','CANCELLED') DEFAULT 'ACTIVE',handled_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,handled_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(handled_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS emergency_contacts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,organization VARCHAR(190),phone VARCHAR(30) NOT NULL,type VARCHAR(50),city VARCHAR(100),created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS alerts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,type ENUM('critical','warning','system') DEFAULT 'system',title VARCHAR(190) NOT NULL,message TEXT NOT NULL,severity ENUM('low','medium','high','critical') DEFAULT 'medium',is_read BOOLEAN DEFAULT FALSE,created_by BIGINT UNSIGNED,read_by BIGINT UNSIGNED,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,read_at DATETIME,FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(read_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS emergency_protocol_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,protocol ENUM('patrol','broadcast','escalate') NOT NULL,triggered_by BIGINT UNSIGNED NOT NULL,status VARCHAR(30) DEFAULT 'TRIGGERED',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(triggered_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT UNSIGNED,action VARCHAR(100) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT UNSIGNED,details JSON,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS system_settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,setting_key VARCHAR(100) UNIQUE NOT NULL,setting_value VARCHAR(500) NOT NULL,description VARCHAR(255),updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT INTO system_settings(setting_key,setting_value,description) VALUES ('escalation_threshold_hours','4','Escalation threshold'),('max_reports_per_user_hour','5','Report rate limit'),('fake_report_auto_archive_hours','48','Fake report archive delay'),('alert_sensitivity','medium','Alert sensitivity') ON DUPLICATE KEY UPDATE setting_key=VALUES(setting_key);
